<template><div class="exp-compare-wrap"><div class="exp-compare compare-desktop" tabindex="0" aria-label="方向方案对照表"><table><caption class="sr-only">三个方向的依据、风险与候选方向</caption><thead><tr><th scope="col">比较项</th><th v-for="item in items" :key="item.id" scope="col"><small>{{ item.role }}</small>{{ item.title }}</th></tr></thead><tbody><tr><th scope="row">匹配判断</th><td v-for="item in items" :key="item.id">{{ item.fit.label }}</td></tr><tr><th scope="row">支持依据</th><td v-for="item in items" :key="item.id"><ul><li v-for="e in item.evidence" :key="e">{{ e }}</li></ul></td></tr><tr><th scope="row">主要风险</th><td v-for="item in items" :key="item.id" class="ws-attention">{{ item.risk }}</td></tr><tr><th scope="row">候选方向</th><td v-for="item in items" :key="item.id"><button class="btn" :aria-pressed="selectedId===item.id" @click="$emit('pick',item.id)">{{ selectedId===item.id?'当前候选':'选择方向' }}</button></td></tr></tbody></table></div><div class="compare-mobile"><section v-for="criterion in ['匹配判断','支持依据','主要风险']" :key="criterion" class="compare-criterion"><h3>{{ criterion }}</h3><article v-for="item in items" :key="item.id"><strong>{{ item.role }} · {{ item.title }}</strong><p v-if="criterion==='匹配判断'">{{ item.fit.label }}</p><ul v-else-if="criterion==='支持依据'"><li v-for="e in item.evidence" :key="e">{{ e }}</li></ul><p v-else class="ws-attention">{{ item.risk }}</p></article></section><fieldset class="compare-candidates"><legend>选择候选方向</legend><label v-for="item in items" :key="item.id"><input type="radio" name="compare-candidate" :checked="selectedId===item.id" @change="$emit('pick',item.id)"/>{{ item.title }}</label></fieldset></div></div></template>
